select * from ( select a.REGIST_SEQNO registSeqno, IFNULL(t2.pbc_code,a.PBC_PROD_ID) pbcProdId, IFNULL(t2.pbc_code,replace(a.PBC_PROD_ID,'INS','')) pbcPordIdOut, a.MDATE mdate, a.CCY ccy, a.PROFIT profit, a.PROFIT_CNY profitCny, a.CUSTOM_PROFIT customProfit, a.CUSTOM_PROFIT_CNY customProfitCny, a.CUS_YEAR_YIELD cusYearYield, a.SEND_STATUS sendStatus, a.SUBMIT_TIME submitTime, a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, a.SUMIT_SEQ sumitSeq, a.STATUS_DATE statusDate, a.PBC_SUBMIT_DEADLINE pbcSubmitDeadline, a.SUBMIT_DEADLINE submitDeadline, a.STATUS status, a.CREATE_USER createUser, a.ORG_CODE orgCode, a.CREATE_DEPT createDept, a.CREATE_TIME createTime, a.UPDATE_USER updateUser, a.UPDATE_TIME updateTime, ifnull(t1.INSIDE_PROD_ID,b.PROD_ID) prodId, a.DATUUID datuuid from PBC_COL_PRD_BASEINFO_END_SUB a LEFT JOIN(SELECT inside_prod_id, pbc_code FROM pbc_prod_assetpool_code WHERE status = 'E' AND code_type = '01') t1 ON t1.PBC_CODE = a.PBC_PROD_ID left join b on a.PBC_PROD_ID = b.PBC_PROD_ID LEFT JOIN( SELECT inside_prod_id, pbc_code FROM pbc_prod_assetpool_code WHERE status='E' AND code_type='01' )t2 ON t2.inside_prod_id=b.PROD_ID LEFT JOIN CHB_ORG_REGIST_BANK_CODE CORBC ON CORBC.PBC_BANK_CODE = b.ISSUE_PARTY_ID LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = CORBC.ORG_CODE
#{items,jdbcType=VARCHAR}
AND b.PROD_ID IN
#{item,jdbcType=VARCHAR}
null) OR a.REGIST_SEQNO in (
#{items,jdbcType=VARCHAR}
and trim(a.REGIST_SEQNO) in
#{item,jdbcType=VARCHAR}
and a.SEND_STATUS in
#{item,jdbcType=VARCHAR}
and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart}
and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd}
and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') >= #{submitTimeStart}
and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') <= #{submitTimeEnd}
and DATE_FORMAT(a.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{pbcSubmitDeadlineDateStart}
and DATE_FORMAT(a.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{pbcSubmitDeadlineDateEnd}
and DATE_FORMAT(a.MDATE,'%Y-%m-%d') >= #{mdateStart}
and DATE_FORMAT(a.MDATE,'%Y-%m-%d') <= #{mdateEnd}
) a ORDER BY a.pbcProdId,a.ccy,a.pbcSubmitDeadline ASC, a.statusDate DESC

