mapper.insert:
insert into pbc_col_prd_baseinfo_end_sub_HIS () select REGIST_SEQNO, PBC_PROD_ID, MDATE, CCY, PROFIT, PROFIT_CNY, CUSTOM_PROFIT, CUSTOM_PROFIT_CNY, CUS_YEAR_YIELD, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from pbc_col_prd_baseinfo_end_sub where PBC_PROD_ID in
#{item.pbcProdId,jdbcType=CHAR}
and SEND_STATUS in ('02','03')

insert into pbc_col_prd_baseinfo_end_sub () select HIS_NO, PBC_PROD_ID, MDATE, CCY, PROFIT, PROFIT_CNY, CUSTOM_PROFIT, CUSTOM_PROFIT_CNY, CUS_YEAR_YIELD, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from ( select , rank() over (partition by PBC_PROD_ID order by ifnull(update_time,create_time) desc) ranknum from pbc_col_prd_baseinfo_end_sub_HIS where PBC_PROD_ID in
#{item.pbcProdId,jdbcType=CHAR}
) as t where t.ranknum = 1

mapper.delete:
delete from pbc_col_prd_baseinfo_end_sub_HIS
where PBC_PROD_ID in (
select  t1.PBC_PROD_ID
from (
select PBC_PROD_ID ,
rank() over (partition by PBC_PROD_ID order by ifnull(update_time,create_time) desc) ranknum
from pbc_col_prd_baseinfo_end_sub_HIS
where
PBC_PROD_ID in

    #{item.pbcProdId,jdbcType=CHAR}

) t1
where t1.ranknum = 1
)

mapper.select:
select info.prod_id as prodId,/*产品代码*/ infosub.PBC_PROD_ID as pbcProdId,/*人行产品代码*/ info.VDATE VDATE,/*产品起息日*/ info.BASIC basic,/*产品计息基础*/ sub.regist_seqno regSeq,/*已报送登记*/ deal.status status, deal.SETTDATE_DATE mdate, info.PRODTYPE prodtype, info.CASH_MANA_CATE cashManaCate from chb_prd_baseinfo info inner join infosub on info.prod_id = infosub.prod_id left join PBC_COL_PRD_BASEINFO_END_SUB sub on infosub.PBC_PROD_ID = sub.PBC_PROD_ID and sub.send_status in ('02','03') left join chb_prd_deal deal on ifnull(info.fprod_id,info.prod_id) = ifnull(deal.fprod_id,deal.prod_id) and deal.TRADE_TYPE in
#{dto,jdbcType=VARCHAR}
where info.status in ('E','M') and info.fprod_id is null
info.prod_id = #{prdEndSub.prodId,jdbcType = VARCHAR}

select ifnull(temp.fprod_id,temp.prod_id) as prodId,temp.settdate_date as mdate from (select deal.prod_id, deal.fprod_id, deal.settdate_date from chb_prd_deal deal where ifnull(DATE_FORMAT(deal.update_time, '%Y-%m-%d'),DATE_FORMAT(deal.create_time, '%Y-%m-%d')) <= #{batchDate, jdbcType = VARCHAR} and deal.trade_type in
#{dto,jdbcType=VARCHAR}
and deal.status in ('E', 'D','M') union all select deal.prod_id, deal.fprod_id, deal.settdate_date from chb_prd_deal deal where DATE_FORMAT(deal.settdate_date, '%Y-%m-%d') <= #{batchDate, jdbcType = VARCHAR} and deal.trade_type in
#{dto,jdbcType=VARCHAR}
and deal.status in ('E', 'D','M') union all select feeinfo.prod_id, feeinfo.fprod_id,deal1.settdate_date from (select fee.prod_id, fee.fprod_id from chb_prd_fee_deal fee where ifnull(DATE_FORMAT(fee.update_time, '%Y-%m-%d'),DATE_FORMAT(fee.create_time, '%Y-%m-%d')) = #{batchDate,jdbcType = VARCHAR} and fee.status in ('E','D','M') group by fee.prod_id, fee.fprod_id) feeinfo inner join chb_prd_deal deal1 on deal1.prod_id = feeinfo.prod_id and deal1.trade_type in
#{dto,jdbcType=VARCHAR}
and DATE_FORMAT(deal1.settdate_date, '%Y-%m-%d') <= #{batchDate,jdbcType = VARCHAR} and deal1.status in('E','M')) temp where 1=1
and ifnull(temp.fprod_id,temp.prod_id) in
#{dto,jdbcType=VARCHAR}
group by ifnull(temp.fprod_id,temp.prod_id),temp.settdate_date

select pos.CDATE, pos.PROD_ID, pos.CCY,pos.FEE_TYPE,sum(ifnull(pos.AMT,0)) amt from CHB_PRD_FEE_POSITION pos inner join (select max(CDATE) cdate,prod_id from CHB_PRD_FEE_POSITION group by prod_id) a on a.prod_id=pos.prod_id and a.CDATE=pos.CDATE where pos.FEE_TYPE = '01'
#{item.prodId,jdbcType=VARCHAR}
group by pos.CDATE, pos.PROD_ID, pos.CCY,pos.FEE_TYPE

mapper.delete:
delete from PBC_COL_PRD_BASEINFO_END_SUB where PBC_PROD_ID in
#{dto.pbcProdId,jdbcType=VARCHAR}
AND SEND_STATUS = '01'
